+		.regs = s5k5e9_regs,
+	};
+
+	ret = s5k5e9_write_reg_list(s5k5e9, &regs);
+	if (ret)
+		return ret;
+
+	ret = s5k5e9_write_reg_list(s5k5e9, &s5k5e9->cur_mode->reg_list);
+	if (ret)
+		return ret;
+
+	ret = __v4l2_ctrl_handler_setup(&s5k5e9->ctrl_handler);
+	if (ret)
+		return ret;
+
+	ret = s5k5e9_write(s5k5e9, 0x0100, 1, 0x01);
+	if (ret)
+		return ret;
+
+	return 0;
+}
